context.raw_tex:
Formally, let $\mathcal{X}$ be a finite-dimensional real Hilbert space. Given a number  $n\geq 1$ of smooth functions $f_i:\mathcal{X}\rightarrow \mathbb{R}$, $i\in[n]\coloneqq \{1,\ldots,n\}$, 
 the finite-sum optimization problem is
\begin{equation}
\min_{x\in\mathcal{X}} \,f(x)\coloneqq \frac{1}{n}\sum_{i=1}^n f_i(x).\label{eqp1}
\end{equation}

We make the following assumptions on the functions.
\begin{itemize}
\item There exists $L>0$ such that $f_i$ is $L$-smooth for every $i\in[n]$; that is, $f_i$ is differentiable on $\mathcal{X}$ and for every $(x,y)\in\mathcal{X}^2$, $\|\nabla f_i(x)-\nabla f_i(y)\|\leq L \|x-y\|$.
\item There exists $\tau\in [0,L]$ such that $f_i$ is $\tau$-weakly convex for every $i\in[n]$; that is, $f_i+\frac{\tau}{2} \|\cdot\|^2$ is convex \cite{nur73}.
\item $f$ is lower bounded: $f^\star \coloneqq \inf f > -\infty$. 
\end{itemize}


In addition, we establish linear convergence when 
$f$ satisfies the 
Polyak--{\L}ojasiewicz (P{\L}) condition with constant $\mu>0$, or in short is $\mu$-P{\L} \cite{kar16}:
 \begin{equation*}
\|\nabla f(x)\|^2\geq 2\mu\big(f(x)-f^\star\big),\ \mbox{for every }x\in\mathcal{X}.
\end{equation*}
In this case, $\mu\leq L$ and we define the condition number $\kappa\coloneqq \frac{L}{\mu}\geq 1$.  


\begin{algorithm}[H] 
		\caption{\algn{PAGE}}\label{alg1}
		\begin{algorithmic}
			\STATE  \textbf{input:} initial estimate $x^0$, initial gradient estimate $g^0$, stepsize $\gamma>0$, probability $p\in (0,1]$.
			\FOR{$t=0, 1, \ldots$}
			\STATE $x^{t+1} \coloneqq x^t - \gamma g^t$
			\STATE flip a coin $\theta^t = (1$ with probability $p$, $0$ otherwise)
			\IF{$\theta^t=0$}
			\STATE pick $i^t \in [n]$ uniformly at random
			\STATE $g^{t+1} \coloneqq g^t +\nabla f_{i^t}(x^{t+1})-\nabla f_{i^t}(x^{t})$
			\ELSE
			\STATE $g^{t+1} \coloneqq \nabla f(x^{t+1})$
			\ENDIF 
			\ENDFOR
		\end{algorithmic}
	\end{algorithm}

\begin{equation}
\Psi^t \coloneqq f(x^t)-f^\star -b\gamma \sqnorm{\nabla f(x^t)} + \frac{a \gamma}{p} \sqnorm{g^t-\nabla f(x^t)} + \frac{b \gamma}{p} \sqnorm{g^t},\label{eqly}
\end{equation}

for some constants $a>0$ and $b\in[ 0, \frac{1}{2\gamma L}]$. Since $f$ is $L$-smooth, we have 
$f(x^t)-f^\star \geq  \frac{1}{2L}\sqnorm{\nabla f(x^t)}$
\cite[eq. 3.5]{bub15}, 
so that the condition $b\gamma  \leq \frac{1}{2L}$ guarantees that $\Psi^t$ is a valid Lyapunov function: we have $\Psi^t\geq 0$, and $\Psi^t \rightarrow 0$ implies $\sqnorm{g^t}\rightarrow 0$, $\sqnorm{\nabla f(x^t)}\rightarrow 0$, and
$f(x^t)-f^\star \rightarrow 0$.

