Formally, let $\mathcal{X}$ be a finite-dimensional real Hilbert space. Given a number  $n\geq 1$ of smooth functions $f_i:\mathcal{X}\rightarrow \mathbb{R}$, $i\in[n]\coloneqq \{1,\ldots,n\}$, 
 the finite-sum optimization problem is
\begin{equation}
\min_{x\in\mathcal{X}} \,f(x)\coloneqq \frac{1}{n}\sum_{i=1}^n f_i(x).\label{eqp1}
\end{equation}

We make the following assumptions on the functions.
\begin{itemize}
\item There exists $L>0$ such that $f_i$ is $L$-smooth for every $i\in[n]$; that is, $f_i$ is differentiable on $\mathcal{X}$ and for every $(x,y)\in\mathcal{X}^2$, $\|\nabla f_i(x)-\nabla f_i(y)\|\leq L \|x-y\|$.
\item There exists $\tau\in [0,L]$ such that $f_i$ is $\tau$-weakly convex for every $i\in[n]$; that is, $f_i+\frac{\tau}{2} \|\cdot\|^2$ is convex \cite{nur73}.
\item $f$ is lower bounded: $f^\star \coloneqq \inf f > -\infty$. 
\end{itemize}

\begin{algorithm}[H] 
		\caption{\algn{PAGE}}\label{alg1}
		\begin{algorithmic}
			\STATE  \textbf{input:} initial estimate $x^0$, initial gradient estimate $g^0$, stepsize $\gamma>0$, probability $p\in (0,1]$.
			\FOR{$t=0, 1, \ldots$}
			\STATE $x^{t+1} \coloneqq x^t - \gamma g^t$
			\STATE flip a coin $\theta^t = (1$ with probability $p$, $0$ otherwise)
			\IF{$\theta^t=0$}
			\STATE pick $i^t \in [n]$ uniformly at random
			\STATE $g^{t+1} \coloneqq g^t +\nabla f_{i^t}(x^{t+1})-\nabla f_{i^t}(x^{t})$
			\ELSE
			\STATE $g^{t+1} \coloneqq \nabla f(x^{t+1})$
			\ENDIF 
			\ENDFOR
		\end{algorithmic}
	\end{algorithm}

\begin{equation}
\Psi^t \coloneqq f(x^t)-f^\star -b\gamma \sqnorm{\nabla f(x^t)} + \frac{a \gamma}{p} \sqnorm{g^t-\nabla f(x^t)} + \frac{b \gamma}{p} \sqnorm{g^t},\label{eqly}
\end{equation}

\begin{theorem}[linear convergence]\label{theo1}
Suppose that $f$ is $\mu$-P{\L} for some $\mu>0$. 
In \algn{PAGE} with Lyapunov function \eqref{eqly}, suppose that
\begin{equation*}
\gamma \leq %\min\left(
\frac{1}{L\left(1+\sqrt{ \frac{4\tau}{L+\tau}}\sqrt{  \frac{1-p}{p}}\right)}, 
\end{equation*}
with the additional requirement $\gamma<\frac{1}{L}$ if $\tau=0$, 
\begin{equation*}
a= 1-\frac{\gamma (L-\tau)}{2}\in \left( \frac{1}{2},1\right], \quad b= \frac{\gamma (L-\tau)}{2}\in \left[0, \frac{1}{2}\right).
\end{equation*}
Then $b\gamma  < \frac{1}{2L}$, and 
\algn{PAGE}
converges linearly:  for every $t\geq 0$, 
\begin{equation*}
\Exp{\Psi^{t}}\leq \rho^t \Psi^0,
\end{equation*}
where 
\begin{equation*}
\rho\coloneqq \max\left(1-(1-2b)\gamma\mu,1-p\left(1-\frac{1}{2a}\right)\right)<1.
\end{equation*}
Also, $\Psi^t\rightarrow 0$ 
almost surely.
\end{theorem}

Suppose that $f$ is $\mu$-P{\L} for some $\mu>0$. 
In \algn{PAGE} with Lyapunov function \eqref{eqly}, suppose that
\begin{equation*}
\gamma \leq %\min\left(
\frac{1}{L\left(1+\sqrt{ \frac{4\tau}{L+\tau}}\sqrt{  \frac{1-p}{p}}\right)}, 
\end{equation*}
with the additional requirement $\gamma<\frac{1}{L}$ if $\tau=0$, 
\begin{equation*}
a= 1-\frac{\gamma (L-\tau)}{2}\in \left( \frac{1}{2},1\right], \quad b= \frac{\gamma (L-\tau)}{2}\in \left[0, \frac{1}{2}\right).
\end{equation*}

\begin{lemma}\label{lemm2}
Let $g:\mathcal{X}\rightarrow \mathbb{R}$ be an $L$-smooth and $\tau$-weakly convex function for some $L>0$ and $\tau\in [0,L]$. Then, for every $(x,y)\in\mathcal{X}^2$, 
\begin{align*}
\sqnorm{\nabla g(x)- \nabla g(y)}&\leq (L-\tau)\langle \nabla g(x) - \nabla g(y),x-y\rangle + L\tau \sqnorm{x-y}.
\end{align*}
\end{lemma}

\subsection{Proof of Lemma~\ref{lemm2}}

Let $(x,y)\in\mathcal{X}^2$. Since $g+\frac{\tau}{2}\|\cdot\|^2$ is convex and $(L+\tau)$-smooth, its gradient is $\frac{1}{L+\tau}$-cocoercive according to the Baillon--Haddad theorem \cite[Corollary 18.17]{bau17}, so that
\begin{align*}
\sqnorm{\nabla g(x)+\tau x - \nabla g(y)-\tau y} &\leq (L+\tau)\langle \nabla g(x) +\tau x- \nabla g(y)-\tau y,x-y\rangle\\
&=(L+\tau)\langle \nabla g(x) - \nabla g(y),x-y\rangle +  (L+\tau)\tau \sqnorm{x-y}.
\end{align*}
Hence,
\begin{align*}
\sqnorm{\nabla g(x)- \nabla g(y)}&=\sqnorm{\nabla g(x)+\tau x- \nabla g(y)-\tau y}\!-\!2\tau
\langle \nabla g(x) - \nabla g(y),x-y\rangle 
\!-\!\tau^2\sqnorm{x-y}\\
&\leq (L-\tau)\langle \nabla g(x) - \nabla g(y),x-y\rangle + L\tau \sqnorm{x-y}.
\end{align*}\qed

\subsection{Proof of Lemma~\ref{lemm2}}

Let $(x,y)\in\mathcal{X}^2$. Since $g+\frac{\tau}{2}\|\cdot\|^2$ is convex and $(L+\tau)$-smooth, its gradient is $\frac{1}{L+\tau}$-cocoercive according to the Baillon--Haddad theorem \cite[Corollary 18.17]{bau17}, so that
\begin{align*}
\sqnorm{\nabla g(x)+\tau x - \nabla g(y)-\tau y} &\leq (L+\tau)\langle \nabla g(x) +\tau x- \nabla g(y)-\tau y,x-y\rangle\\
&=(L+\tau)\langle \nabla g(x) - \nabla g(y),x-y\rangle +  (L+\tau)\tau \sqnorm{x-y}.
\end{align*}

\subsection{Proof of Theorem~\ref{theo1}}\label{secproof1}

For every $t\geq 0$, let $\mathcal{F}^t$ denote the $\sigma$-algebra generated by the random variables $x^0,g^0,\ldots, x^t,g^t$. For the moment, assume that $a$ and $b$ in \eqref{eqly} satisfy  $a>0$, 
$0\leq b\leq \frac{1}{2}$, $b\gamma  \leq \frac{1}{2L}$, without additional restrictions.


Let $t\geq 0$. We now derive upper bounds for the terms in $\Exp{\Psi^{t+1}\;|\;\mathcal{F}^t}$.

\noindent \textbf{First}, we have the descent property \cite[Lemma 4]{ric21}
\begin{align*}
f(x^{t+1}) -f^\star &\leq f(x^t)  -f^\star -\frac{\gamma}{2} \sqnorm{\nabla f(x^t)} +\frac{ \gamma }{2}\sqnorm{g^{t}-\nabla f(x^t)}+ \left(\frac{ L}{2}-\frac{1}{2\gamma}\right)\sqnorm{x^{t+1}-x^t}\\
&=f(x^t)  -f^\star -\frac{\gamma}{2} \sqnorm{\nabla f(x^t)} +\frac{ \gamma }{2}\sqnorm{g^{t}-\nabla f(x^t)}+ \left(\frac{ L\gamma^2}{2}-\frac{\gamma}{2}\right)\sqnorm{g^t}.
\end{align*}
\textbf{Second}, we have 
\begin{align*}
\Exp{\sqnorm{g^{t+1}-\nabla f(x^{t+1})}\;|\;\mathcal{F}^t} &= (1-p)\Exp{\sqnorm{g^{t+1}-\nabla f(x^{t+1})}\;|\;\theta^t=0,\mathcal{F}^t},
\end{align*}
and by decomposing 
the expected squared norm into its squared mean and variance, we obtain
\begin{align*}
&\Exp{\sqnorm{g^{t+1}-\nabla f(x^{t+1})}\;|\;\mathcal{F}^t} = (1-p)\sqnorm{g^{t}-\nabla f(x^t)}\\
&\qquad +\frac{1-p}{n}\sum_{i=1}^n\sqnorm{\nabla f_i(x^{t+1})-\nabla f_i(x^{t})-\nabla f(x^{t+1})+\nabla f(x^t)}.
\end{align*}
\textbf{Third}, we have
\begin{align*}
\Exp{\sqnorm{g^{t+1}}\;|\;\mathcal{F}^t} &= p \sqnorm{\nabla f(x^{t+1})}+ (1-p)\Exp{\sqnorm{g^{t+1}}\;|\;\theta^t=0,\mathcal{F}^t}\\
&=p \sqnorm{\nabla f(x^{t+1})}+ (1-p)\sqnorm{g^{t}+\nabla f(x^{t+1})-\nabla f(x^t)}\\
&\quad +\frac{1-p}{n}\sum_{i=1}^n\sqnorm{\nabla f_i(x^{t+1})-\nabla f_i(x^{t})-\nabla f(x^{t+1})+\nabla f(x^t)}.
\end{align*}
Using the fact that $g^t=-\frac{1}{\gamma}(x^{t+1}-x^t)$, we obtain
\begin{align*}
\sqnorm{g^{t}+\nabla f(x^{t+1})-\nabla f(x^t)} &= \sqnorm{g^{t}} + \sqnorm{\nabla f(x^{t+1})-\nabla f(x^t)} +2\!\left\langle g^{t},\nabla f(x^{t+1})-\nabla f(x^t)\right\rangle\\
&=\sqnorm{g^{t}} + \sqnorm{\nabla f(x^{t+1})-\nabla f(x^t)}\\
&\quad -\frac{2}{\gamma}\left\langle x^{t+1}-x^t,\nabla f(x^{t+1})-\nabla f(x^t)\right\rangle.
\end{align*}
The negative inner product $-\frac{2}{\gamma}\left\langle x^{t+1}-x^t,\nabla f(x^{t+1})-\nabla f(x^t)\right\rangle$ that appears is crucial, as it enables the cancellation of positive terms using Lemma~\ref{lemm2}.

Since $f=\frac{1}{n}\sum_{i=1}^n f_i$, we have
\begin{align*}
&\frac{1}{n}\sum_{i=1}^n\sqnorm{\nabla f_i(x^{t+1})-\nabla f_i(x^{t})-\nabla f(x^{t+1})+\nabla f(x^t)}\\
&\quad= \frac{1}{n}\sum_{i=1}^n\sqnorm{\nabla f_i(x^{t+1})-\nabla f_i(x^{t})} -\sqnorm{\nabla f(x^{t+1})-\nabla f(x^t)}.
\end{align*}
Therefore,
\begin{align*}
\Exp{\sqnorm{g^{t+1}}\;|\;\mathcal{F}^t} &=p \sqnorm{\nabla f(x^{t+1})}+ (1-p)\sqnorm{g^{t}}\\
&\quad -\frac{2(1-p)}{\gamma}\left\langle x^{t+1}-x^t,\nabla f(x^{t+1})-\nabla f(x^t)\right\rangle\\
 &\quad +\frac{1-p}{n}\sum_{i=1}^n\sqnorm{\nabla f_i(x^{t+1})-\nabla f_i(x^{t})}.
\end{align*}

Moreover, by Lemma~\ref{lemm2} and the smoothness and weak convexity of the functions $f_i$, we obtain
\begin{align*}
\frac{1}{n}\sum_{i=1}^n \sqnorm{\nabla f_i(x^{t+1})- \nabla f_i(x^t)}&\leq\frac{1}{n}\sum_{i=1}^n \Big( (L-\tau)\big\langle \nabla f_i(x^{t+1}) - \nabla f_i(x^t),x^{t+1}-x^t\big\rangle \\
&\quad\left.{}+ L\tau \sqnorm{x^{t+1}-x^t}\right)\\
&= (L-\tau)\big\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\big\rangle \\
&\quad+ L\tau \sqnorm{x^{t+1}-x^t}.
\end{align*}
The inner products $(L-\tau)\big\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\big\rangle$ will be canceled using the negative inner product $-\frac{2}{\gamma}\left\langle x^{t+1}-x^t,\nabla f(x^{t+1})-\nabla f(x^t)\right\rangle$ that appeared above, while the terms 
$\sqnorm{x^{t+1}-x^t}$ will be canceled by choosing $\gamma$ sufficiently small and using the negative term $(\frac{ L}{2}-\frac{1}{2\gamma})\sqnorm{x^{t+1}-x^t}$ arising in the descent property.

Thus, 
\begin{align*}
\Exp{\sqnorm{g^{t+1}-\nabla f(x^{t+1})}\;|\;\mathcal{F}^t} 
&\leq (1-p)\sqnorm{g^{t}-\nabla f(x^t)}\!+\!
\frac{1-p}{n}\sum_{i=1}^n \sqnorm{\nabla f_i(x^{t+1})- \nabla f_i(x^t)}\\
&\leq (1-p)\sqnorm{g^{t}-\nabla f(x^t)}+ (1-p)L\tau \sqnorm{x^{t+1}-x^t}\\
&\quad +(1-p)(L-\tau)  \left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle
\end{align*}
and
\begin{align*}
\Exp{\sqnorm{g^{t+1}}\;|\;\mathcal{F}^t} 
&\leq p \sqnorm{\nabla f(x^{t+1})}+ (1-p)\sqnorm{g^{t}}\\
&\quad -\frac{2(1-p)}{\gamma}\left\langle \nabla f(x^{t+1})-\nabla f(x^t),x^{t+1}-x^t\right\rangle\\
 &\quad +(1-p)(L-\tau)\left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle\\
&\quad +(1-p)L\tau \sqnorm{x^{t+1}-x^t}\\
 &= p\sqnorm{\nabla f(x^{t+1})}+ (1-p)\big(1+L\tau\gamma^2\big)
\sqnorm{g^{t}} \\
&\quad +(1-p)\left(L- \tau-\frac{2}{\gamma}\right) \left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle .
\end{align*}
Hence, combining the inequalities for these terms, we obtain
\begin{align*}
\Exp{\Psi^{t+1}\;|\;\mathcal{F}^t}&\leq
f(x^t)  -f^\star -\frac{\gamma}{2} \sqnorm{\nabla f(x^t)} +\frac{ \gamma }{2}\sqnorm{g^{t}-\nabla f(x^t)}+ \left(\frac{ L\gamma^2}{2}-\frac{\gamma}{2}\right)\sqnorm{g^t} \\
&\quad -b\gamma\sqnorm{\nabla f(x^{t+1})}
+\frac{a\gamma}{p} (1-p)\sqnorm{g^{t}-\nabla f(x^t)}
+ a\gamma^3 L\tau \frac{1-p}{p}\sqnorm{g^t}\\
&\quad+a\gamma (L-\tau) \frac{1-p}{p}\left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle+b\gamma\sqnorm{\nabla f(x^{t+1})}\notag\\
&\quad+\frac{b\gamma}{p}  (1-p)\big(1+L\tau\gamma^2\big)\sqnorm{g^{t}}\\
&\quad+ \big(b\gamma (L-\tau)-2b\big) \frac{1-p}{p}\left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle\notag\\
&= f(x^t)  -f^\star  -\frac{\gamma}{2} \sqnorm{\nabla f(x^t)}+\frac{a\gamma}{p}\left(1-p\left(1-\frac{1 }{2a}\right)  \right)\sqnorm{g^{t}-\nabla f(x^t)}\notag\\
&\quad+\frac{b\gamma}{p}  (1-p)\sqnorm{g^{t}}
+\frac{\gamma}{2}\left(L\gamma-1+ 2(a+b)\gamma^2 L\tau \frac{1-p}{p}\right)\sqnorm{g^{t}}\notag\\
&\quad+ \big((a+b)\gamma (L-\tau)-2b\big) \frac{1-p}{p}\left\langle \nabla f(x^{t+1}) - \nabla f(x^t),x^{t+1}-x^t\right\rangle.
\end{align*}
To cancel the inner product, we set
\begin{equation}
b\coloneqq \frac{a\gamma (L-\tau)}{2-\gamma(L-\tau)},\label{eqbb}
\end{equation}
so that $(a+b)\gamma (L-\tau)-2b=0$. Note that $\gamma\leq \frac{1}{L}$ implies $2-\gamma(L-\tau)\geq 1$. Moreover,
a sufficient condition for $L\gamma-1+ 2(a+b)\gamma^2 L\tau \frac{1-p}{p}\leq 0$ is  \cite[Lemma 5]{ric21}
\begin{equation}
\gamma \leq \frac{1}{L+\sqrt{2(a+b)L\tau \frac{1-p}{p}}}.\label{eqlllo}
\end{equation}
To avoid the dependence of $b$ on $\gamma$, we derive from $\gamma\leq \frac{1}{L}$ that 
\begin{equation*}
b\leq  \frac{a (L-\tau)}{L+\tau},%\label{eqww}
\end{equation*}
so that $a+b\leq  \frac{2aL}{L+\tau}$. Therefore, a sufficient condition for \eqref{eqlllo} is
\begin{equation}
\gamma \leq \frac{1}{L+\sqrt{ \frac{4aL}{L+\tau}L\tau \frac{1-p}{p}}}=\frac{1}{L\left(1+\sqrt{ \frac{4a\tau}{L+\tau}}\sqrt{  \frac{1-p}{p}}\right)}.\label{eqlllo2}
\end{equation}
If we additionally assume $a\leq 1$,  the dependence on $a$ can be eliminated with the sufficient condition 
\begin{equation*}
\gamma \leq \frac{1}{L\left(1+\sqrt{ \frac{4\tau}{L+\tau}}\sqrt{  \frac{1-p}{p}}\right)},
\end{equation*}
as stated in the theorem.

Therefore, since the sufficient conditions above are supposed to hold, we have
\begin{align*}
\Exp{\Psi^{t+1}\;|\;\mathcal{F}^t}&\leq
 f(x^t)  -f^\star  -\frac{\gamma}{2} \sqnorm{\nabla f(x^t)}+\frac{a\gamma}{p}\left(1-p\left(1-\frac{1 }{2a}\right)  \right)\sqnorm{g^{t}-\nabla f(x^t)}\\
&\quad+\frac{b\gamma}{p}  (1-p)\sqnorm{g^{t}}\\
&= f(x^t)  -f^\star  -\gamma\left(\frac{1}{2}-b\right)\sqnorm{\nabla f(x^t)} -b\gamma \sqnorm{\nabla f(x^t)}\\
&\quad+\frac{a\gamma}{p}\left(1-p\left(1-\frac{1}{2a}\right)  \right)\sqnorm{g^{t}-\nabla f(x^t)}+\frac{b\gamma}{p}  (1-p)\sqnorm{g^{t}}.
\end{align*}
To obtain a contraction, we need $a>\frac{1}{2}$ and $b<\frac{1}{2}$. The choice 
\begin{equation*}
a= 1-\frac{\gamma (L-\tau)}{2}, \quad b= \frac{\gamma (L-\tau)}{2},
\end{equation*}
with the additional condition $\gamma<\frac{1}{L}$ if $\tau=0$, satisfies  these two inequalities, as well as \eqref{eqbb}, $a\leq 1$, and $b \gamma \leq \frac{1}{2L}$.

Finally, under the assumption that $f$ is $\mu$-P{\L}, we have
\begin{equation*}
\|\nabla f(x^t)\|^2\geq 2\mu\big(f(x^t)-f^\star\big).
\end{equation*}
Therefore,
\begin{align}
\Exp{\Psi^{t+1}\;|\;\mathcal{F}^t}&\leq  \big(1-(1-2b)\gamma\mu\big)\big(f(x^t)  -f^\star\big)  -b\gamma \sqnorm{\nabla f(x^t)}\notag\\
&\quad+\frac{a\gamma}{p}\left(1-p\left(1-\frac{1}{2a}\right)  \right)\sqnorm{g^{t}-\nabla f(x^t)}+\frac{b\gamma}{p}  (1-p)\sqnorm{g^{t}}\notag\\
&\leq  \big(1-(1-2b)\gamma\mu\big)\big(f(x^t)  -f^\star  -b\gamma \sqnorm{\nabla f(x^t)}\big)\notag\\
&\quad+\frac{a\gamma}{p}\left(1-p\left(1-\frac{1}{2a}\right)  \right)\sqnorm{g^{t}-\nabla f(x^t)}+\frac{b\gamma}{p}  (1-p)\sqnorm{g^{t}}\notag\\
&\leq \max\left(1-(1-2b)\gamma\mu,1-p\left(1-\frac{1}{2a}\right),1-p\right)\Psi^t\notag\\
&= \max\left(1-(1-2b)\gamma\mu,1-p\left(1-\frac{1}{2a}\right)\right)\Psi^t.\label{eqrec2b}
\end{align}
Using the tower rule of expectations, we can unroll the recursion in \eqref{eqrec2b} to obtain the unconditional expectation of $\Psi^{t+1}$. Moreover, using classical results on supermartingale convergence \cite[Proposition A.4.5]{ber15}, it follows from \eqref{eqrec2b} that $\Psi^t\rightarrow 0$ almost surely. \qed
